Start-Process powershell.exe -Verb RunAs -ArgumentList '-NoProfile -ExecutionPolicy Bypass -Command "cmd /c assoc .ps1=Microsoft.PowerShellScript.1; cmd /c ""ftype Microsoft.PowerShellScript.1=\"\"%SystemRoot%\System32\WindowsPowerShell\v1.0\powershell.exe\"\" -File \"%1\" %*""; reg add HKCR\.ps1 /ve /d Microsoft.PowerShellScript.1 /f; reg add HKCR\Microsoft.PowerShellScript.1\Shell /ve /d Open /f; reg add HKCR\Microsoft.PowerShellScript.1\Shell\Open\Command /ve /d ""\""%%SystemRoot%%\System32\WindowsPowerShell\v1.0\powershell.exe\"" -File \""%%1\"" %%*"" /f"'
